import 'package:dio/dio.dart';
import 'package:family_veda/models/app_notification.dart';
import 'package:family_veda/models/approved_guidance.dart';
import 'package:family_veda/models/member.dart';
import 'package:family_veda/models/triage_case.dart';
import 'package:family_veda/services/api/api_client.dart';

/// Safe submission feedback; never exposes backend response contents.
class ComplaintSubmissionException implements Exception {
  const ComplaintSubmissionException(this.message);
  final String message;
}

const uncertainComplaintSubmission =
    'Could not confirm submission. Check your requests before retrying to avoid sending the same request twice.';

String _submissionId(Map<String, dynamic>? body) {
  final id = body?['id'];
  if (id is! String || id.trim().isEmpty) {
    throw const FormatException('Missing submission identifier');
  }
  return id;
}

abstract interface class PatientApi {
  Future<List<Member>> getMembers();
  Future<List<TriageCase>> getCases(String memberId);
  Future<Map<String, dynamic>> getCaseStatus(String caseId);
  Future<List<AppNotification>> getNotifications();
  Future<void> subscribeDevice(String token);
  Future<ApprovedGuidance?> getApprovedGuidance({
    required String caseId,
    required String memberId,
  });
  Future<ApprovedFamilialRisk?> getApprovedFamilialRisk(String memberId);
  Future<String> submitComplaint({
    required String memberId,
    required String chiefComplaint,
    required int durationDays,
    required int severity,
    required List<String> symptoms,
    String? notes,
  });
}

enum MobileDevicePlatform {
  android('ANDROID'),
  ios('IOS');

  const MobileDevicePlatform(this.apiValue);

  final String apiValue;
}

class DioPatientApi implements PatientApi {
  const DioPatientApi(this._client, {required this.devicePlatform});

  final ApiClient _client;
  final MobileDevicePlatform devicePlatform;

  @override
  Future<List<Member>> getMembers() async {
    final response = await _client.dio.get<dynamic>('/families/me');
    final data = response.data;
    if (data is! Map<String, dynamic> || data['members'] is! List) {
      throw const FormatException('Expected family members list');
    }
    return _listFrom(
      data['members'],
    ).map(Member.fromJson).toList(growable: false);
  }

  @override
  Future<List<TriageCase>> getCases(String memberId) async {
    final response = await _client.dio.get<dynamic>(
      '/members/$memberId/triage-cases',
      queryParameters: {'page': 1, 'pageSize': 50},
    );
    return _listFrom(
      response.data,
    ).map(TriageCase.fromJson).toList(growable: false);
  }

  @override
  Future<Map<String, dynamic>> getCaseStatus(String caseId) async {
    final response = await _client.dio.get<Map<String, dynamic>>(
      '/triage-cases/$caseId',
    );
    return response.data ??
        (throw const FormatException('Empty case status response'));
  }

  @override
  Future<List<AppNotification>> getNotifications() async {
    final portal = await _client.dio.get<dynamic>('/notifications');
    final items = _listFrom(portal.data).map(AppNotification.fromJson).toList();
    try {
      final triage = await _client.dio.get<dynamic>(
        '/notifications/inbox',
        queryParameters: {'page': 1, 'pageSize': 50},
      );
      items.addAll(_listFrom(triage.data).map(AppNotification.fromJson));
    } on Object {
      // The triage inbox is available to family users only. Keep portal
      // notifications visible for doctors and when the legacy inbox fails.
    }
    items.sort((a, b) => b.createdAt.compareTo(a.createdAt));
    return items;
  }

  @override
  Future<void> subscribeDevice(String token) async {
    await _client.dio.post<void>(
      '/notifications/subscribe',
      data: {'deviceToken': token, 'platform': devicePlatform.apiValue},
    );
  }

  @override
  Future<ApprovedGuidance?> getApprovedGuidance({
    required String caseId,
    required String memberId,
  }) async {
    final response = await _client.dio.get<Map<String, dynamic>>(
      '/triage-cases/$caseId/approved-guidance',
      queryParameters: {'memberId': memberId},
    );
    final data = response.data;
    return data == null ? null : ApprovedGuidance.fromPatientJson(data);
  }

  @override
  Future<ApprovedFamilialRisk?> getApprovedFamilialRisk(String memberId) async {
    final response = await _client.dio.get<Map<String, dynamic>>(
      '/members/$memberId/familial-risk',
    );
    final data = response.data;
    return data == null ? null : ApprovedFamilialRisk.fromPatientJson(data);
  }

  @override
  Future<String> submitComplaint({
    required String memberId,
    required String chiefComplaint,
    required int durationDays,
    required int severity,
    required List<String> symptoms,
    String? notes,
  }) async {
    var episodeSaved = false;
    try {
      final episodeResponse = await _client.dio.post<Map<String, dynamic>>(
        '/members/$memberId/episodes',
        data: {
          'durationDays': durationDays,
          'severity': severity,
          'symptoms': {chiefComplaint, ...symptoms}.toList(),
          if (notes != null && notes.trim().isNotEmpty) 'notes': notes.trim(),
        },
      );
      episodeSaved = true;
      final episodeId = _submissionId(episodeResponse.data);
      final response = await _client.dio.post<Map<String, dynamic>>(
        '/episodes/$episodeId/triage',
      );
      return _submissionId(response.data);
    } on DioException catch (error) {
      final status = error.response?.statusCode;
      if (!episodeSaved && (status == 403 || status == 404)) {
        throw const ComplaintSubmissionException(
          'This request could not be sent for this family member. Adults must submit their own requests. For a child, a guardian must grant health-condition consent in Privacy & Access first.',
        );
      }
      if (status == 401) {
        throw const ComplaintSubmissionException(
          'Your session has expired. Sign in again, then check your requests before retrying.',
        );
      }
      if (!episodeSaved && (status == 400 || status == 422)) {
        throw const ComplaintSubmissionException(
          'This request was not sent. Check the details and try again.',
        );
      }
      if (!episodeSaved && status == 429) {
        throw const ComplaintSubmissionException(
          'Too many requests. Please wait before trying again.',
        );
      }
      throw const ComplaintSubmissionException(uncertainComplaintSubmission);
    } on Object {
      // Parsing can fail after the server has saved the request.
      throw const ComplaintSubmissionException(uncertainComplaintSubmission);
    }
  }
}

List<Map<String, dynamic>> _listFrom(dynamic value) {
  final raw = value is Map<String, dynamic>
      ? (value['items'] ?? value['data'] ?? const <dynamic>[])
      : value;
  if (raw is! List) throw const FormatException('Expected a list response');
  return raw.cast<Map<String, dynamic>>();
}
